export const sum=a=>a.reduce((s,v)=>{if(!Number.isSafeInteger(v)||!Number.isSafeInteger(s+v))throw Error('원 단위 합계가 안전한 정수 범위를 초과합니다.');return s+v;},0);
function fraction(x){const match=String(x).match(/^(-?)(\d+)(?:\.(\d+))?(?:e([+-]?\d+))?$/i);if(!match)throw Error('유효한 십진수가 필요합니다');const [,sign,a,b='',exponent='0']=match;let n=BigInt(sign+a+b),scale=b.length-Number(exponent);return scale<0?[n*10n**BigInt(-scale),1n]:[n,10n**BigInt(scale)];}
export function mul(amount,...rates){let n=BigInt(amount),d=1n;for(const r of rates){const [a,b]=fraction(r);n*=a;d*=b;}const result=Number((n+d/2n)/d);if(!Number.isSafeInteger(result))throw Error('계산 결과가 원 단위 안전 범위를 초과합니다. 기준값·성과·연봉을 낮추세요.');return result;}
export function ratio(amount,numerator,denominator,...rates){let n=BigInt(amount)*BigInt(numerator),d=BigInt(denominator);for(const r of rates){const [a,b]=fraction(r);n*=a;d*=b;}if(d<=0n)throw Error('기준값은 0보다 커야 합니다');const result=Number((n+d/2n)/d);if(!Number.isSafeInteger(result))throw Error('계산 결과가 원 단위 안전 범위를 초과합니다. 기준값·성과·연봉을 낮추세요.');return result;}
// Largest remainder allocation, deterministic id tie-break, preserves every KRW.
export function allocate(total,items){if(total<0)return allocate(-total,items).map(v=>-v);const t=BigInt(total),w=items.reduce((s,i)=>s+BigInt(i.weight),0n);if(!w)return items.map(()=>0);const a=items.map((i,index)=>({index,id:i.id,n:t*BigInt(i.weight)/w,r:t*BigInt(i.weight)%w}));let left=t-a.reduce((s,i)=>s+i.n,0n);const order=[...a].sort((x,y)=>x.r===y.r?x.id.localeCompare(y.id):x.r>y.r?-1:1);for(let i=0;left>0n;i++,left--)order[i%order.length].n++;return a.sort((x,y)=>x.index-y.index).map(i=>Number(i.n));}
export function split3(v){return allocate(v,[0,1,2].map(i=>({id:String(i),weight:1})));}
export function years(s){return Array.from({length:s.endYear-s.startYear+1},(_,i)=>s.startYear+i);}
