export function salaryAt(p,y,s){let salary=p.salary;for(let year=s.dataStartYear??s.startYear;year<=y;year++){const explicit=p.salaries[year];if(explicit!==undefined&&explicit!==null&&explicit!=='')salary=Number(explicit);else if(year>(s.dataStartYear??s.startYear))salary=mul(salary,1+Number(p.growthByYear[year]??p.growth??s.settings.growth));if(p.cap>0)salary=Math.min(salary,p.cap);}return salary;}
export function workDeduction(g){if(g<=5000000)return mul(g,.7);if(g<=15000000)return 3500000+mul(g-5000000,.4);if(g<=45000000)return 7500000+mul(g-15000000,.15);if(g<=100000000)return 12000000+mul(g-45000000,.05);return Math.min(20000000,14750000+mul(g-100000000,.02));}
export function taxAndInsurance(gross,year,t){const caps=Object.keys(t.pensionCaps).map(Number).sort((a,b)=>a-b);const cap=t.pensionCaps[year]??t.pensionCaps[caps.filter(v=>v<=year).at(-1)]??79080000;const pensionRate=Math.min(t.pensionMaxRate??0.065,Number((t.pensionStart+Math.max(0,year-2026)*t.pensionStep).toFixed(6)));const pension=t.pensionPaidByYear?.[year]??mul(Math.min(gross,cap),pensionRate),health=Math.min(mul(gross,t.health),t.healthAnnualCap??55100880),care=mul(health,t.care),employment=mul(gross,t.employment),insurance=pension+health+care+employment;const deduction=workDeduction(gross),taxable=Math.max(0,gross-deduction-(t.deductInsurance?insurance:0));let prev=0,income=0;for(const [ceiling,rate]of t.brackets){const to=ceiling??taxable;const amount=Math.max(0,Math.min(taxable,to)-prev);income+=mul(amount,rate);if(taxable<=to)break;prev=to;}const local=mul(income,t.local);return {gross,year,deduction,taxable,income,local,pension,pensionRate,pensionCap:cap,health,care,employment,insurance,total:income+local+insurance};}
const emptyParts=()=>Object.fromEntries(TYPES.map(k=>[k,0]));
const row=y=>({year:y,gross:emptyParts(),net:emptyParts(),salary:0,allowance:0,details:[],reasons:[]});
export function calculatePerson(p,s,scenario){const cfg=s.settings,windowYears=years(s),ys=Array.from({length:s.endYear-Math.min(s.dataStartYear??s.startYear,s.startYear)+1},(_,i)=>Math.min(s.dataStartYear??s.startYear,s.startYear)+i),events=[],accrual=ys.map(row);function add(type,origin,payYear,gross,liquidYears){const id=`${p.id}:${origin}:${type}`;events.push({id,personId:p.id,type,origin,payYear,gross,net:0,liquidYears,reason:null});}
 for(const y of ys){const a=accrual.find(v=>v.year===y),salary=salaryAt(p,y,s),base=salary+(p.includeAllowance?p.allowance:0),study=!!p.study[y];a.salary=salary;a.allowance=p.allowance;a.gross.salary=salary+p.allowance;const opi1=study?0:mul(base,cfg.opi1Rate),tai=study?0:mul(base,cfg.taiRate);add('opi1',y,y+cfg.opi1Delay,opi1,[y+cfg.opi1Delay]);add('tai',y,y+cfg.taiDelay,tai,[y+cfg.taiDelay]);const performance=scenario.performance[y]??0,threshold=cfg.thresholds[y]??(y<=2028?200:100);let reason=scenario.unpaid[y]||scenario.opi2Factor===0?'사용자 미지급 가정':performance<threshold?'지급 기준 미달':null;const amount=reason?0:ratio(cfg.opi2Base,BigInt(mul(1000000,performance))*BigInt(base),BigInt(mul(1000000,cfg.performanceBase))*BigInt(cfg.salaryBase),cfg.coefficients[p.division],study?cfg.studyCoefficient:1,scenario.opi2Factor);const pay=Number(cfg.opi2PayYears[y]??y+cfg.opi2Delay);add('opi2',y,pay,amount,[pay,pay+1,pay+2]);events.at(-1).reason=reason;a.reasons.push(reason||'지급 기준 충족');}
 const shareCount=p.includePSU?mul(cfg.psuShares[p.grade],scenario.psuMode==='zero'?0:p.psuMultiplier):0;const psuGross=mul(shareCount,p.psuPrice),psuParts=split3(psuGross);cfg.psuYears.forEach((y,i)=>{if(y>=ys[0]&&y<=s.endYear)add('psu',y,y,psuParts[i],[y+p.psuLock]);});
 const taxYears=[...new Set([...ys,...events.map(e=>e.payYear)])].sort((a,b)=>a-b),taxLog=[];for(const y of taxYears){const baseGross=salaryAt(p,y,s)+p.allowance,baseTax=taxAndInsurance(baseGross,y,cfg.tax),ev=events.filter(e=>e.payYear===y),bonus=sum(ev.map(e=>e.gross)),fullTax=taxAndInsurance(baseGross+bonus,y,cfg.tax),increment=Math.max(0,fullTax.total-baseTax.total),deductions=allocate(increment,ev.map(e=>({id:e.id,weight:e.gross})));ev.forEach((e,i)=>{e.deduction=deductions[i];e.net=e.gross-e.deduction;});const a=accrual.find(v=>v.year===y);if(a){a.net.salary=baseGross-baseTax.total;a.baseTax=baseTax;}taxLog.push({person:p.name,year:y,baseGross,bonus,baseTax,fullTax,increment,allocation:ev.map(e=>({type:e.type,origin:e.origin,gross:e.gross,deduction:e.deduction,net:e.net})),futureAssumption:y>s.endYear});}
 for(const e of events){const a=accrual.find(v=>v.year===e.origin);a.gross[e.type]+=e.gross;a.net[e.type]+=e.net;a.details.push(e);e.tranches=allocate(e.net,e.liquidYears.map((y,i)=>({id:String(i),weight:1}))).map((value,i)=>({year:e.liquidYears[i],net:value,gross:allocate(e.gross,e.liquidYears.map((v,j)=>({id:String(j),weight:1})))[i],origin:e.origin,payYear:e.payYear,type:e.type}));}
 const cashflow=windowYears.map(row);for(const c of cashflow){const a=accrual.find(v=>v.year===c.year);c.net.salary=a.net.salary;c.gross.salary=a.gross.salary;for(const e of events)for(const tr of e.tranches)if(tr.year===c.year){c.net[e.type]+=tr.net;c.gross[e.type]+=tr.gross;c.details.push(tr);}c.netTotal=sum(Object.values(c.net));c.grossTotal=sum(Object.values(c.gross));}
 let cumulative=0;cashflow.forEach(c=>{cumulative+=c.netTotal;c.cumulative=cumulative;});let unpaidStock=0,paidLockedStock=0,unpaidCash=0;for(const e of events){if(['opi2','psu'].includes(e.type)){const remainder=sum(e.tranches.filter(t=>t.year>s.endYear).map(t=>t.net));if(e.payYear>s.endYear)unpaidStock+=remainder;else paidLockedStock+=remainder;}else if(e.payYear>s.endYear)unpaidCash+=e.net;}
 for(const a of accrual){a.netTotal=sum(Object.values(a.net));a.grossTotal=sum(Object.values(a.gross));a.netCash=a.net.salary+a.net.opi1+a.net.tai;a.netStock=a.net.opi2+a.net.psu;a.lockedStock=sum(a.details.filter(e=>['opi2','psu'].includes(e.type)).flatMap(e=>e.tranches.filter(t=>t.year>a.year)).map(t=>t.net));}
 const selectedAccrual=accrual.filter(a=>a.year>=s.startYear);const openingEvents=events.filter(e=>e.origin<s.startYear);const openingStock=sum(openingEvents.filter(e=>['opi2','psu'].includes(e.type)).flatMap(e=>e.tranches.filter(t=>t.year>=s.startYear)).map(t=>t.net));const openingCash=sum(openingEvents.filter(e=>!['opi2','psu'].includes(e.type)).flatMap(e=>e.tranches.filter(t=>t.year>=s.startYear)).map(t=>t.net));return {person:clone(p),accrual:selectedAccrual,cashflow,events,taxLog,psuShares:shareCount,opening:{stock:openingStock,cash:openingCash,total:openingStock+openingCash},locked:{unpaidStock,paidLockedStock,unpaidCash,totalStock:unpaidStock+paidLockedStock},totals:{grossAccrual:sum(selectedAccrual.map(a=>a.grossTotal)),netAccrual:sum(selectedAccrual.map(a=>a.netTotal)),netLiquid:cumulative,contract:sum(selectedAccrual.map(a=>a.salary)),grossLiquid:sum(cashflow.map(c=>c.grossTotal))}};
}
export function calculate(s,scenario=s.scenarios[s.activeScenario]){validateState(s);const people=s.people.slice(0,1).map(p=>calculatePerson(p,s,scenario));function combine(key){return years(s).map(y=>{const rows=people.map(p=>p[key].find(r=>r.year===y)),r=row(y);for(const type of TYPES){r.gross[type]=sum(rows.map(a=>a.gross[type]));r.net[type]=sum(rows.map(a=>a.net[type]));}r.grossTotal=sum(Object.values(r.gross));r.netTotal=sum(Object.values(r.net));r.salary=sum(rows.map(a=>a.salary));r.allowance=sum(rows.map(a=>a.allowance));r.netCash=r.net.salary+r.net.opi1+r.net.tai;r.netStock=r.net.opi2+r.net.psu;r.lockedStock=sum(rows.map(a=>a.lockedStock||0));r.details=rows.flatMap(a=>a.details);r.reasons=rows.flatMap(a=>a.reasons);return r;});}const accrual=combine('accrual'),cashflow=combine('cashflow');let c=0;cashflow.forEach(r=>r.cumulative=c+=r.netTotal);const locked=Object.fromEntries(['unpaidStock','paidLockedStock','unpaidCash','totalStock'].map(k=>[k,sum(people.map(p=>p.locked[k]))]));const totals=Object.fromEntries(['grossAccrual','netAccrual','netLiquid','contract','grossLiquid'].map(k=>[k,sum(people.map(p=>p.totals[k]))]));const opening=Object.fromEntries(['stock','cash','total'].map(k=>[k,sum(people.map(p=>p.opening[k]))]));return {people,accrual,cashflow,locked,opening,totals,scenario:clone(scenario),period:{start:s.startYear,end:s.endYear},disclaimer:DISCLAIMER};}
export function comparePresets(s){const base=defaults().scenarios.middle,down=defaults().scenarios.downturn,opt=clone(base);opt.name='낙관적 예시 ×1.25';opt.performance=Object.fromEntries(years(s).map(y=>[y,mul(1000000,base.performance[y]??0)*1.25/1000000]));return {basic:calculate(s,base),conservative:calculate(s,down),optimistic:calculate(s,opt)};}
