export function validationReport(settings){const s=defaults();if(settings)s.settings=clone(settings);const reports=[];for(const [k,expected]of Object.entries(BENCHMARKS)){const scenario=clone(k==='middle'?s.scenarios.middle:s.scenarios.downturn);if(k==='downturnZero')scenario.psuMode='zero';const r=calculate(s,scenario),checks=[];const add=(label,actual,exp)=>checks.push({label,actual,expected:exp,difference:actual-exp,percent:exp?(actual-exp)/exp:0,warning:Math.abs(actual-exp)>Math.max(10000,exp*s.settings.warningTolerance)});r.cashflow.forEach((row,i)=>add(String(row.year),row.netTotal,expected.annual[i]));add('5년 누적',r.totals.netLiquid,expected.total);reports.push({key:k,name:k==='middle'?'중간 전망 + PSU 600주':k==='downturn'?'2028·2029 OPI2 미지급 + PSU 600주':'2028·2029 OPI2 미지급 + PSU 0배',checks,result:r});}return reports;}
