 const mergeKnown=(target,source)=>{if(!source||typeof source!=='object'||Array.isArray(source))throw Error('불러오기 실패: 설정 객체가 필요합니다');for(const k of Object.keys(target)){if(!Object.hasOwn(source,k))continue;if(['salaries','growthByYear','study','opi2PayYears','thresholds','pensionCaps','pensionPaidByYear','taxSettlementYearByOrigin','insuranceSettlementYearByOrigin','gradeByYear','ratingByYear','workBonusByYear','paymentRateByYear','paymentDateByYear','paymentDateConfirmedByYear','expectedPaymentYearByYear','vwapWeekByYear','vwapMonthByYear','vwapTwoMonthsByYear','closingPriceByYear','manualGrossByYear','performance','unpaid'].includes(k)){target[k]=clone(source[k]);}else if(target[k]&&typeof target[k]==='object'&&!Array.isArray(target[k]))mergeKnown(target[k],source[k]);else target[k]=clone(source[k]);}};
 if(raw.opi2Policy!==undefined)mergeKnown(s.opi2Policy,raw.opi2Policy);s.opi2Policy.workBonusDefinition='confirmed_separate';if(s.opi2Policy.reportedSharesDefinition==='pending')s.opi2Policy.reportedSharesDefinition='gross_equivalent';mergeKnown(s.settings,raw.settings);mergeKnown(s.scenarios,raw.scenarios);mergeKnown(s.people[0],raw.people[0]);s.people[0].id='1';s.mode='individual';s.schemaVersion=2;if(s.opi2Policy.simpleInput!==false){if(s.opi2Policy.donationRate)s.migrationNotice='구형 기부 비율은 적용하지 않으며 기부금은 0원으로 고정합니다.';if(Object.keys(s.opi2Policy.manualGrossByYear??{}).length)s.migrationNotice='구형 직접 금액과 기부 비율은 적용하지 않습니다. OPI1·OPI2 계산 조건은 유지됩니다.';s.opi2Policy.donationRate=0;s.opi2Policy.manualGrossByYear={};}validateState(s);
