export function validateState(s){const fail=m=>{throw Error('불러오기 실패: '+m);};const finite=(v,min,max,name,integer=false)=>{if(typeof v!=='number'||!Number.isFinite(v)||v<min||v>max||(integer&&!Number.isSafeInteger(v)))fail(name+' 범위를 확인하세요');};if(!s||s.schemaVersion!==2)fail('지원하는 schemaVersion은 2입니다');finite(s.dataStartYear,2020,s.startYear,'연봉 기준연도',true);finite(s.startYear,2020,2050,'시작연도',true);finite(s.endYear,s.startYear,Math.min(s.startYear+14,2050),'종료연도',true);validatePolicy(s.opi2Policy);if(s.mode!=='individual')fail('계산모드');if(!Array.isArray(s.people)||s.people.length!==1)fail('개인 1명의 데이터가 필요합니다');if(!['middle','downturn','custom'].includes(s.activeScenario))fail('시나리오');const yearMap=(m,name)=>{if(!m||typeof m!=='object'||Array.isArray(m))fail(name+'은 연도별 객체여야 합니다');for(const y of Object.keys(m))if(!/^\d{4}$/.test(y)||Number(y)<2020||Number(y)>2065)fail(name+' 연도 키');};const cfg=s.settings;if(!cfg?.tax)fail('설정 누락');for(const k of ['opi1Rate','taiRate','studyCoefficient'])finite(cfg[k],0,2,k);for(const k of ['opi1Delay','taiDelay','opi2Delay'])finite(cfg[k],0,10,k,true);for(const k of ['opi2Base','salaryBase'])finite(cfg[k],1,100000000000,k,true);finite(cfg.performanceBase,1,100000,'기준성과');finite(cfg.growth,-.5,1,'기본 인상률');for(const d of ['메모리','공통','파운드리·시스템LSI'])finite(cfg.coefficients?.[d],0,10,'사업부 계수');for(const p of s.people){for(const k of ['salaries','growthByYear','study'])yearMap(p[k],k);if(typeof p.name!=='string'||p.name.length>40)fail('이름');if(!Object.keys(cfg.coefficients).includes(p.division)||!['메모리','공통','파운드리·시스템LSI'].includes(p.division))fail('소속');if(!['CL1·CL2','CL3·CL4'].includes(p.grade))fail('직급');for(const k of ['salary','allowance','cap','psuPrice'])finite(p[k],0,100000000000,k,true);if(typeof p.includeAllowance!=='boolean'||typeof p.includePSU!=='boolean')fail('개인 체크박스 값');for(const v of Object.values(p.study||{}))if(typeof v!=='boolean')fail('학술연수 체크박스 값');finite(p.growth,-.5,1,'인상률');finite(p.psuMultiplier,0,2,'PSU 배수');finite(p.psuLock,0,10,'매도제한',true);for(const v of Object.values(p.salaries||{}))if(v!==''&&v!==null)finite(v,0,100000000000,'연도 연봉',true);for(const v of Object.values(p.growthByYear||{}))if(v!==''&&v!==null)finite(v,-.5,1,'연도 인상률');if(!p.study||!p.salaries||!p.growthByYear)fail('개인 연도별 설정');}for(const [m,name]of [[cfg.opi2PayYears,'지급연도'],[cfg.thresholds,'지급기준'],[cfg.tax.pensionCaps,'연금상한'],[cfg.tax.pensionPaidByYear,'실제 연금 납입액']])yearMap(m,name);for(const v of Object.values(cfg.opi2PayYears))finite(v,s.dataStartYear,2065,'지급연도',true);for(const [y,v]of Object.entries(cfg.opi2PayYears))if(v<Number(y))fail('지급연도는 성과연도 이후');for(const v of Object.values(cfg.thresholds))finite(v,0,100000,'지급기준');for(const v of Object.values(cfg.psuShares))finite(v,0,100000,'약정주식',true);if(!Array.isArray(cfg.psuYears)||cfg.psuYears.length!==3||new Set(cfg.psuYears).size!==3)fail('PSU 지급연도');for(const v of cfg.psuYears)finite(v,2020,2050,'PSU 지급연도',true);for(const v of Object.values(cfg.tax.pensionPaidByYear))finite(v,0,100000000000,'실제 연금 납입액',true);for(const v of Object.values(cfg.tax.pensionCaps))finite(v,0,100000000000,'국민연금상한',true);finite(cfg.tax.healthAnnualCap,0,100000000000,'건강보험 상한',true);finite(cfg.warningTolerance,0,.5,'검증 경고 허용률');for(const k of ['local','pensionStart','pensionStep','pensionMaxRate','employment','health','care'])finite(cfg.tax[k],0,1,k);if(typeof cfg.tax.deductInsurance!=='boolean')fail('보험료 공제 설정');if(!Array.isArray(cfg.tax.brackets)||cfg.tax.brackets.length!==8)fail('세율구간');let prev=0;cfg.tax.brackets.forEach(([cap,rate],i)=>{if(i<7){finite(cap,prev+1,100000000000,'과표상한',true);prev=cap;}else if(cap!==null)fail('마지막 과표상한은 null');finite(rate,0,.9,'소득세율');});for(const k of ['middle','downturn','custom']){const sc=s.scenarios?.[k];if(!sc||typeof sc.name!=='string'||!sc.performance||!sc.unpaid)fail('시나리오 '+k);yearMap(sc.performance,'성과전망');yearMap(sc.unpaid,'미지급');for(const v of Object.values(sc.unpaid))if(typeof v!=='boolean')fail('미지급 체크박스 값');finite(sc.opi2Factor,0,3,'OPI2 가정배율');if(!['zero','normal'].includes(sc.psuMode))fail('PSU 선택');for(const v of Object.values(sc.performance))finite(v,0,100000,'사업성과');}if(!s.display||!['korean','decimal'].includes(s.display.format)||!['net','gross'].includes(s.display.tax)||!['accrual','cashflow'].includes(s.display.basis))fail('화면설정');return true;}

